-- "Trong 1 suất có": bảng thành phần Viện in trong ảnh suất món ăn, Gemini CHÉP lại (không viết), nhận khi cộng kcal các dòng lệch tổng của món không quá 1%; bỏ tên tiếng Anh, ô Viện để trống ghi trống, sửa tay 1 dòng bị tách (HAN-113050)
CREATE TABLE thanh_phan_suat (
  id SERIAL PRIMARY KEY,
  ma_so TEXT NOT NULL REFERENCES mon_tra_cuu(ma_so) ON DELETE CASCADE,
  thu_tu INTEGER NOT NULL CHECK (thu_tu >= 1),
  ten_thanh_phan TEXT NOT NULL,
  -- Ô Viện để trống (không cân) thì để trống, không ghi 0
  so_gam NUMERIC(7, 1) CHECK (so_gam >= 0),
  so_calo NUMERIC(7, 1) CHECK (so_calo >= 0),
  nguon TEXT NOT NULL,
  -- Đường dẫn ảnh của Viện có in bảng này, để đối chiếu
  lien_ket TEXT NOT NULL,
  -- Ngày chép từ ảnh
  ngay_hieu_luc DATE NOT NULL,
  UNIQUE (ma_so, thu_tu)
);

-- Nhận 350 món (2209 dòng); loại 8 món vì cộng không khớp hoặc không có bảng: HAN-111024, HAN-111015, HAN-123035, HAP-211043, HAN-122021, SFF-211096, HAN-111001, HAP-223007
